'use client';

import * as React from 'react';
import './label.css';

/* LABEL: text in a set role.
 *   engraved, small   the mono label with a lip, uppercase (small at 8.5)
 *   title, heading    an object's name, a page title
 *   query             a pinned query's words
 *   count, cell       a mono number; a mono table cell
 *   value, value-small  a measured value in mono (22, 12)
 *   display, display-quiet  a large line and its quieter continuation
 *   readout, readout-dim  mono on graphite, and the same in its dim ink
 *   on-graphite       sans text on graphite chrome
 *   dark              an engraving on dark chrome
 * tone="accent" turns it green without a lip (a rule that says what a drop will do).
 * placeholder shows in ink3 at 500 while the label is empty; as="input" makes an editable label that keeps the look. */

export type LabelVariant =
  | 'engraved' | 'small' | 'title' | 'heading' | 'query' | 'count' | 'cell' | 'value' | 'value-small'
  | 'display' | 'display-quiet' | 'readout' | 'readout-dim' | 'on-graphite' | 'dark';

export interface LabelProps extends React.HTMLAttributes<HTMLElement> {
  variant?: LabelVariant;
  /** accent: green, no lip. */
  tone?: 'accent';
  as?: 'span' | 'b' | 'i' | 'small' | 'div' | 'h2' | 'h3' | 'p' | 'td' | 'th' | 'input';
  /** Shown in ink3 at 500 while the label is empty (a span), or the input's placeholder. */
  placeholder?: string;
  /** as="input" only. */
  value?: string;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
}

export const Label = React.forwardRef<HTMLElement, LabelProps>(function Label({ variant = 'engraved', tone, as = 'span', placeholder, className, ...props }, ref) {
  const Tag = as as React.ElementType;
  const hint = as === 'input' ? { placeholder } : { 'data-placeholder': placeholder };
  return <Tag ref={ref} data-variant={variant} data-tone={tone} className={className ? `mu-label ${className}` : 'mu-label'} {...hint} {...props} />;
});

@import "../tokens.css";

/* Label: text in a set role. Its look is the label recipe (--mu-r-label-*). */
.mu-label { white-space: nowrap; }
.mu-label:is([data-variant="engraved"], [data-variant="small"], [data-variant="dark"]) { font: var(--mu-r-label-engraved-font); letter-spacing: var(--mu-r-label-engraved-tracking); text-transform: var(--mu-r-label-engraved-transform); color: var(--mu-r-label-engraved-color); text-shadow: var(--mu-r-label-engraved-text-shadow); }
.mu-label[data-variant="small"] { font-size: var(--mu-r-label-small-font-size); }
.mu-label[data-variant="dark"] { color: var(--mu-r-label-dark-color); text-shadow: var(--mu-r-label-dark-text-shadow); }
.mu-label[data-variant="title"] { font: var(--mu-r-label-title-font); letter-spacing: var(--mu-r-label-title-tracking); color: var(--mu-r-label-title-color); }
.mu-label[data-variant="heading"] { font: var(--mu-r-label-heading-font); letter-spacing: var(--mu-r-label-heading-tracking); color: var(--mu-r-label-heading-color); }
.mu-label[data-variant="query"] { font: var(--mu-r-label-query-font); letter-spacing: var(--mu-r-label-query-tracking); color: var(--mu-r-label-query-color); }
.mu-label[data-variant="count"] { font: var(--mu-r-label-count-font); letter-spacing: var(--mu-r-label-count-tracking); color: var(--mu-r-label-count-color); }
.mu-label[data-variant="cell"] { font: var(--mu-r-label-cell-font); letter-spacing: var(--mu-r-label-cell-tracking); color: var(--mu-r-label-cell-color); }
.mu-label[data-variant="value"] { font: var(--mu-r-label-value-font); letter-spacing: var(--mu-r-label-value-tracking); color: var(--mu-r-label-value-color); }
.mu-label[data-variant="value-small"] { font: var(--mu-r-label-value-small-font); letter-spacing: var(--mu-r-label-value-small-tracking); color: var(--mu-r-label-value-small-color); }
.mu-label[data-variant="display"] { font: var(--mu-r-label-display-font); letter-spacing: var(--mu-r-label-display-tracking); color: var(--mu-r-label-display-color); }
.mu-label[data-variant="display-quiet"] { font: var(--mu-r-label-display-quiet-font); letter-spacing: var(--mu-r-label-display-quiet-tracking); color: var(--mu-r-label-display-quiet-color); }
.mu-label[data-variant="readout"] { font: var(--mu-r-label-readout-font); letter-spacing: var(--mu-r-label-readout-tracking); color: var(--mu-r-label-readout-color); }
.mu-label[data-variant="on-graphite"] { font: var(--mu-r-label-on-graphite-font); letter-spacing: var(--mu-r-label-on-graphite-tracking); color: var(--mu-r-label-on-graphite-color); }
.mu-label[data-variant="readout-dim"] { font: var(--mu-r-label-readout-font); font-style: normal; letter-spacing: var(--mu-r-label-readout-tracking); color: var(--mu-r-label-readout-dim-color); }
.mu-label[data-variant="display"], .mu-label[data-variant="display-quiet"] { white-space: normal; }
/* Accent: green, no lip; it cross-fades on settle when a host toggles it. */
.mu-label { transition: color var(--mu-spring-settle-d) var(--mu-spring-settle); }
.mu-label[data-tone="accent"] { color: var(--mu-r-label-accent-color); text-shadow: none; }
/* An empty label shows its placeholder. */
.mu-label[data-placeholder]:empty::before { content: attr(data-placeholder); color: var(--mu-r-label-placeholder-color); font-weight: var(--mu-r-label-placeholder-weight); }
input.mu-label::placeholder { color: var(--mu-r-label-placeholder-color); font-weight: var(--mu-r-label-placeholder-weight); opacity: 1; }
/* An editable label: an input that keeps the look and draws no field of its own. */
input.mu-label { box-sizing: content-box; min-width: var(--mu-zero); padding: var(--mu-zero); margin: var(--mu-zero); border: var(--mu-zero); outline: var(--mu-zero); background: transparent; caret-color: var(--mu-green-deep); cursor: text; field-sizing: content; }
